import json

# Try: each pixel expands outward by its value amount (creating adjacent cells)
def expand_pixel(r, c, val):
    """Create a cross pattern centered at (r,c) with arms extending 'val' steps"""
    result = []
    for i in range(max(0, r-val), min(16, r+val+1)):
        result.append((i, c))
    for j in range(max(0, c-val), min(16, c+val+1)):
        result.append((r, j))
    return set(result)

# Pixel 1 expands by 1, Pixel 2 expands by 2
