import json

# Try: each pixel gets expanded by 1 cell in all 8 directions (Moore neighborhood)
def expand_moore(r, c):
    result = [(r,c)]
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < 16 and 0 <= nc < 16:
                result.append((nr, nc))
    return set(result)

output = [[0]*16 for _ in range(16)]
pixels = {}
for pos in expand_moore(1, 4):
    pixels[pos] = 1
